add("gunes-takip-sistemi", "gunes_takip",
 "İki LDR (ışık direnci) güneşin sol ya da sağda olduğunu anlar; servo, güneş panelini daha çok ışık gelen yöne doğru yavaşça döndürür (tek eksenli güneş takibi). Panel gerilimi gerilim bölücüyle okunur ve Seri Monitör'e yazılır. LDR gerilim bölücüsünü, fark okuyup yön bulmayı, ölü bölgeyi ve 5 V'tan yüksek bir gerilimi analog pinle güvenle ölçmeyi öğrenirsin. Simülatörde ışık, LDR ve panel kaydırıcılarından verilir; servo dönünce ışık otomatik değişmez.",
 [UNO, "Breadboard", "2 × LDR (ışık direnci)", "4 × 10 kΩ direnç (iki LDR bölücüsü ve panel gerilim bölücüsü)", "1 × servo motor (SG90)", "1 × güneş paneli (6 V, 200 mA)", "Panel ve LDR'leri taşıyan döner tabla (devre dışı mekanik parça: devre görüntüsünde yoktur)", "Jumper kablolar (15 adet)"],
 [["5V", "Alttaki artı (+) rayı: LDR'lerin üst uçları ve servo VCC"], ["GND (GND2)", "Alttaki eksi (−) rayı: 10 kΩ dirençlerin alt uçları, servo GND ve panelin eksi ucu"], ["A0", "Sol LDR ile 10 kΩ direncin ortak noktası"], ["A1", "Sağ LDR ile 10 kΩ direncin ortak noktası"], ["A2", "Panel gerilim bölücüsünün orta noktası"], ["D9", "Servo sinyali"]],
 ["Devreyi enerjisiz kur: USB kablosu takılı olmasın.",
  "Arduino 5V pinini alttaki artı (+) rayına, GND2 pinini alttaki eksi (−) rayına kablola.",
  "Sol LDR'yi c4 ve c5 deliklerine tak. 10 kΩ direnci d5 ile d9 arasına tak. e4 → artı rayı, A0 → e5, e9 → eksi rayı.",
  "Sağ LDR'yi c12 ve c13 deliklerine tak. 10 kΩ direnci d13 ile d17 arasına tak. e12 → artı rayı, A1 → e13, e17 → eksi rayı.",
  "Servoyu a20 (SIG), a21 (VCC), a22 (GND) deliklerine tak. D9 → e20, e21 → artı rayı, e22 → eksi rayı.",
  "Panel bölücüsü: 10 kΩ direnci d25 ile d29 arasına, ikinci 10 kΩ direnci dikey olarak e25 ile h25 arasına tak. A2 → a25 (orta nokta), j25 → eksi rayı.",
  "Güneş paneli (breadboard dışında, takılı değil): + ucunu e29'a, − ucunu eksi rayına kablola. Panel 6 V'a kadar verir; doğrudan analog pine bağlama, bölücü gerilimi yarıya indirir.",
  "Gerçek sistemde iki LDR'yi panelin sağ ve sol kenarına, aralarına ışığı ayıran bir bölme koyarak monte et.",
  "Kodu yükle (simülatörde çalıştır): sol LDR'yi seçip ışığını azalt ya da sağ LDR'yi seçip artır: servo açısı değişir. İki LDR eşitlenince servo durur."],
 [["Nasıl çalışıyor?", "Her LDR, 10 kΩ dirençle bir gerilim bölücü oluşturur: ışık arttıkça LDR'nin direnci düşer ve ortak noktadaki gerilim (analogRead değeri) yükselir. Kod iki LDR'yi 8 okumanın ortalamasıyla okur ve fark = sag − sol hesaplar. Fark OLU_BOLGE'den (40) büyükse sağ taraf daha aydınlıktır ve servo açısı 1 derece artırılır (tabla sağa döner); fark −40'tan küçükse açı 1 derece azaltılır; aradaysa servo durur (ölü bölge, titremeyi önler). Açı 10°–170° arasında sınırlanır. Servo yavaş hareket eder (yaklaşık saniyede 14°); güneş de yavaş hareket ettiği için bu yeterlidir. Güneş panelinin gerilimi 6 V'a kadar çıkabileceği için A2'ye doğrudan bağlanmaz: iki 10 kΩ direnç gerilimi yarıya indirir, kod okunan değeri 2 ile çarpıp panel gerilimini milivolt olarak yazar."],
  ["Simülatörde gözlenen", "Açılışta \"Gunes takip hazir\" yazıldı; iki LDR eşit (570) olduğunda servo 90°'de kaldı ve panel gerilimi yaklaşık 5591 mV okundu. 3. saniyede sol LDR ışığı 0,3 (değer 75), sağ LDR ışığı 0,9 (değer 853) yapılınca servo 93°'ye, 4,2. saniyede 107°'ye, 5,3. saniyede 110°'ye döndü (sağ daha aydınlık: açı arttı); 4,5. saniyede LDR'ler yeniden eşitlenince servo 110°'de durdu. 7. saniyede durum tersine çevrilince (sol 853, sağ 75) açı düşmeye başladı: 104°, 90° ve 9,5. saniyede 76°'ye indi; LDR'ler eşitlenince 76°'de durdu. Panel ışığı 0,9 iken yaklaşık 5865 mV, 0,5 iken 5259 mV, 0,05 iken 3831 mV okundu. Simülatörde servo dönünce ışık otomatik değişmediği için LDR değerleri kaydırıcıyla elle eşitlendi; gerçek bir kapalı çevrim takip (servo dönünce ışığın dengelenmesi) ve güneşin gerçek davranışı denenemedi. " + GERCEK],
  [SIM_YOK, "Simülatörde güneş, gölge ve ışığın panele geliş açısı yoktur: LDR ve panel ışığı kaydırıcıdan verilir ve servo döndüğünde değişmez. Panel modeli yalnızca ışığa bağlı basit bir gerilim kaynağıdır (sıcaklık, kısmi gölge, ters akım yok). Gerçek LDR'ler farklı değerler verir ve eşleştirilmeleri gerekir; ortam ışığı, bulut ve yansıma yanılma yaratır. Tek eksenli takip gerçek güneşin yüksekliğini (iki eksen) izlemez. Sketch yalnızca Servo.h kullanır; bu başlık gerçek derleme servisinin izinli başlıkları arasındadır."],
  ["Güç ve GND", "Güneş paneli 6 V'a kadar çıkar: doğrudan Arduino analog pinine bağlama (5 V sınırı); bu devredeki gibi gerilim bölücü kullan. Servoyu USB'den beslemek küçük bir SG90 için genellikle yeter, ama panel ağırlığı yükü artırırsa ayrı 5 V kaynak kullan ve GND'yi ortak yap. Dışarıda kullanırken devreyi yağmurdan koru; güneş panelinin ya da pilin kısa devre yapmamasına dikkat et."],
  ["Sık yapılan hatalar", "LDR'leri bölücü direncini unutarak bağlamak (okuma anlamsız olur); sağ ve sol LDR'yi ters monte etmek (tabla güneşten kaçar; kodda artırma ve azaltma yönlerini ters çevirerek düzeltilir); ölü bölgeyi sıfır yapıp servoyu sürekli titretmek; paneli bölücüsüz A2'ye bağlamak; LDR'ler arasına ışığı ayıran bir bölme koymamak (iki LDR aynı ışığı görür); servoyu çok hızlı döndürüp güneşi aşmak."],
  ["Dene", "OLU_BOLGE'yi 20 ve 80 yap, servonun ne zaman durduğunu izle; en yüksek panel gerilimini hatırlayan ve takip sırasında Seri Monitör'e yazan bir değişken ekle; gece iki LDR de karanlıksa servoyu sabaha doğru geri döndüren bir kural ekle."]],
 free=["sp1"])
